/* TALENTS (the matrix's scratch hook): Force on the permanent damage key, summed with the rest and capped with them */
if (key === 'damage' && s.talents && s.talents.force > 0) t += s.talents.force / 1000;

/* The property capstone. */

function applyVitals(state, equipment, items, talents) {
  const v0 = vitalsOf({ levelXp: state.levelXp, skills: state.skills, equipment, items });
  const v = talents ? { ...v0, maxHp: Math.round(v0.maxHp * (1 + (talents.grit || 0) / 1000)), maxMana: Math.round(v0.maxMana * (1 + (talents.reserve || 0) / 1000)) } : v0;
